use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [derive (Debug)] pub (crate) struct HygieneData { # [doc = " Each expansion should have an associated expansion data, but sometimes there's a delay"] # [doc = " between creation of an expansion ID and obtaining its data (e.g. macros are collected"] # [doc = " first and then resolved later), so we use an `Option` here."] local_expn_data : IndexVec < LocalExpnId , Option < ExpnData > > , local_expn_hashes : IndexVec < LocalExpnId , ExpnHash > , # [doc = " Data and hash information from external crates. We may eventually want to remove these"] # [doc = " maps, and fetch the information directly from the other crate's metadata like DefIds do."] foreign_expn_data : FxHashMap < ExpnId , ExpnData > , foreign_expn_hashes : FxHashMap < ExpnId , ExpnHash > , expn_hash_to_expn_id : UnhashMap < ExpnHash , ExpnId > , syntax_context_data : Vec < SyntaxContextData > , syntax_context_map : FxHashMap < SyntaxContextKey , SyntaxContext > , # [doc = " Maps the `local_hash` of an `ExpnData` to the next disambiguator value."] # [doc = " This is used by `update_disambiguator` to keep track of which `ExpnData`s"] # [doc = " would have collisions without a disambiguator."] # [doc = " The keys of this map are always computed with `ExpnData.disambiguator`"] # [doc = " set to 0."] expn_data_disambiguators : UnhashMap < Hash64 , u32 > , }